"""Dataset wrapper for advanced single-star QA pairs generated by caption_advanced.py."""

from __future__ import annotations

import json
from typing import Any, Dict, List

try:
    from .dataset_interpert import StellarQuestionsDataset
except ImportError:
    # When running as main script, use absolute imports
    import os
    import sys
    import numpy as np
    
    ROOT_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    sys.path.append(ROOT_DIR)
    from data.dataset_interpert import StellarQuestionsDataset


class AdvancedStellarQuestionsDataset(StellarQuestionsDataset):
    """
    Extension of `StellarQuestionsDataset` that consumes the JSON produced by
    `caption_advanced.py`. The generated records already include explicit
    `question` and `answer` keys; this wrapper normalises them into the expected
    description format so the base class logic (tokenisation, feature handling,
    split management) operates without modification.
    """

    def _load_data(self) -> None:
        """Load advanced QA samples while preserving base-class behaviour."""
        print(f"Loading advanced QA data from {self.json_file}...")
        with open(self.json_file, "r", encoding="utf-8") as fh:
            incoming = json.load(fh)

        if not isinstance(incoming, list):
            raise ValueError("Advanced dataset JSON must be a list of objects.")

        processed: List[Dict[str, Any]] = []
        for entry in incoming:
            if not isinstance(entry, dict):
                continue

            question = (entry.get("question") or entry.get("Question") or "").strip()
            answer = (entry.get("answer") or entry.get("Answer") or "").strip()

            normalised: Dict[str, Any] = dict(entry)
            normalised["question"] = question
            normalised['answer'] = answer
            normalised['description'] = json.dumps(
                {"Question": question, "Description": answer},
                ensure_ascii=False,
            )
            if 'obsid' not in normalised:
                idx_value = normalised.get('index')
                if idx_value is not None:
                    normalised['obsid'] = idx_value

            processed.append(normalised)

        print(f"Loaded {len(processed)} raw samples from JSON.")

        if self.filter_valid_descriptions:
            before = len(processed)
            processed = [
                sample
                for sample in processed
                if (sample["question"] or sample["answer"])
            ]
            print(f"Filtered to {len(processed)} samples with non-empty QA pairs "
                  f"(removed {before - len(processed)}).")

        self.raw_data = processed

        self.df_indices = []
        for sample in self.raw_data:
            df_idx = sample.get("index")
            if df_idx is not None:
                self.df_indices.append(df_idx)

        if not self.df_indices:
            print("Warning: No dataframe indices found in advanced dataset.")



if __name__ == "__main__":
    from pathlib import Path

    from torch.utils.data import DataLoader

    ROOT_DIR = Path(__file__).resolve().parents[1]
    TOKENIZER_PATH = "/data/.llama/Llama3.2-1B/tokenizer.model"
    json_path = ROOT_DIR / "data" / "dataset" / "advanced_dataset.json"
    features_path = '/data/TalkingLatents/logs/2025-07-29/features.npy'
    features_array = np.load(features_path)
    if not json_path.exists():
        raise SystemExit(f"Expected advanced dataset JSON at {json_path}")

    cache_root = ROOT_DIR / "logs" / "test_dataset" / "advanced_questions"
    cache_root.mkdir(parents=True, exist_ok=True)

    common_kwargs = dict(
        json_file=str(json_path),
        features_array=features_array,
        train_ratio=0.8,
        val_ratio=0.1,
        test_ratio=0.1,
        random_state=1234,
        cache_dir=str(cache_root),
        max_length=256,
        tokenizer_path=TOKENIZER_PATH,
        num_spectral_features=4,
    )

    datasets = {
        split: AdvancedStellarQuestionsDataset(split=split, **common_kwargs)
        for split in ("train", "val", "test")
    }

    for split, dataset in datasets.items():
        print(f"{split.title()} split contains {len(dataset)} samples")

    if len(datasets["train"]) == 0:
        raise SystemExit("Train split is empty; check the dataset JSON content.")

    loader = DataLoader(datasets["train"], batch_size=2, shuffle=False)
    batch = next(iter(loader))
    print("Batch keys:", list(batch.keys()))
    print("input_ids shape:", batch["input_ids"].shape)
    print("target_ids shape:", batch["target_ids"].shape)
    print("features shape: ", batch["features"].shape, batch["masked_spectra"].shape)
    print("feature_start_idx sample:", batch["feature_start_idx"][:5])
    print("answer_start_idx sample:", batch["answer_start_idx"][:5])

    sample = datasets["train"][0]
    print("Sample question:", sample.get("input_text", "")[:120])
    print("input ids: ", sample.get("input_ids", [0])[:120])
    print("Sample answer:", sample.get("target_text", "")[:120])

